#!/usr/bin/env python3
"""
Script to reproduce the bug with mocked classmethod.
"""

import pytest
from oop_ext.interface import Interface, ImplementsInterface, AssertImplements


def test_requires_declaration_bug():
    """Test case that reproduces the bug described in the issue."""

    class IFoo(Interface):
        @classmethod
        def foo(cls):
            ""

    @ImplementsInterface(IFoo)
    class FooImplementation:
        @classmethod
        def foo(cls):
            ""

    # Import mocker fixture manually to simulate the test
    from unittest.mock import MagicMock

    # Simulate what mocker.spy does - it replaces the method with a MagicMock
    original_foo = FooImplementation.foo
    mock_foo = MagicMock(wraps=original_foo)
    FooImplementation.foo = mock_foo

    try:
        # This should pass but currently fails
        AssertImplements(FooImplementation, IFoo, requires_declaration=True)
        print("SUCCESS: AssertImplements passed!")
    except AssertionError as e:
        print(f"FAILED: {e}")
        raise
    finally:
        # Restore original method
        FooImplementation.foo = original_foo


def test_is_method_with_magicmock():
    """Test to check if _IsMethod correctly identifies MagicMock objects."""
    from oop_ext.interface._interface import _IsMethod
    from unittest.mock import MagicMock

    # Regular function
    def regular_func():
        pass

    # MagicMock object
    mock_func = MagicMock()

    print(f"_IsMethod(regular_func): {_IsMethod(regular_func)}")
    print(f"_IsMethod(mock_func): {_IsMethod(mock_func)}")


if __name__ == "__main__":
    print("Testing _IsMethod behavior:")
    test_is_method_with_magicmock()

    print("\nTesting the main issue:")
    try:
        test_requires_declaration_bug()
    except Exception as e:
        print(f"Test failed as expected: {e}")

