"""
Comprehensive test to make sure the fix works and doesn't break existing functionality.
"""

import pytest
from oop_ext.interface import Interface, ImplementsInterface, AssertImplements
from unittest.mock import Mock, MagicMock


def test_mock_classmethod_with_spy():
    """Test the exact scenario from the bug report."""
    class IFoo(Interface):
        @classmethod
        def foo(cls):
            ""

    @ImplementsInterface(IFoo)
    class FooImplementation:
        @classmethod
        def foo(cls):
            ""

    # Simulate mocker.spy behavior
    original_foo = FooImplementation.foo
    mock_foo = MagicMock(wraps=original_foo)
    FooImplementation.foo = mock_foo

    try:
        AssertImplements(FooImplementation, IFoo, requires_declaration=True)
        assert True  # Should not raise
    finally:
        # Restore
        FooImplementation.foo = original_foo


def test_mock_instance_method():
    """Test that mocked instance methods also work."""
    class IBar(Interface):
        def bar(self):
            ""

    @ImplementsInterface(IBar)
    class BarImplementation:
        def bar(self):
            ""

    # Mock instance method
    original_bar = BarImplementation.bar
    mock_bar = MagicMock(wraps=original_bar)
    BarImplementation.bar = mock_bar

    try:
        AssertImplements(BarImplementation, IBar, requires_declaration=True)
        assert True  # Should not raise
    finally:
        # Restore
        BarImplementation.bar = original_bar


def test_regular_methods_still_work():
    """Ensure regular methods still work as before."""
    class IBaz(Interface):
        def baz(self):
            ""

        @classmethod
        def class_baz(cls):
            ""

    @ImplementsInterface(IBaz)
    class BazImplementation:
        def baz(self):
            ""

        @classmethod
        def class_baz(cls):
            ""

    # This should work without any mocking
    AssertImplements(BazImplementation, IBaz, requires_declaration=True)


def test_mock_signature_checking():
    """Test that signature checking still works with mocks."""
    class ISignature(Interface):
        def method(self, a, b=None):
            ""

    @ImplementsInterface(ISignature)
    class SignatureImplementation:
        def method(self, a, b=None):
            ""

    # Mock with correct signature
    original_method = SignatureImplementation.method
    mock_method = MagicMock(wraps=original_method)
    SignatureImplementation.method = mock_method

    try:
        AssertImplements(SignatureImplementation, ISignature, requires_declaration=True)
        assert True  # Should not raise
    finally:
        SignatureImplementation.method = original_method


def test_non_callable_mocks_are_not_considered_methods():
    """Test that non-callable mocks are not considered methods."""
    # This test verifies that our _IsMethod logic is sound
    from oop_ext.interface._interface import _IsMethod

    # Callable mock should be considered a method
    callable_mock = MagicMock()
    assert _IsMethod(callable_mock) == True

    # Non-callable mock should not be considered a method in interface context
    # But this is tricky to test since mocks are generally callable


def test_other_mock_types():
    """Test other mock types."""
    from oop_ext.interface._interface import _IsMethod

    # Test Mock (parent class of MagicMock)
    regular_mock = Mock()
    assert _IsMethod(regular_mock) == True

    # Test MagicMock
    magic_mock = MagicMock()
    assert _IsMethod(magic_mock) == True


if __name__ == "__main__":
    test_mock_classmethod_with_spy()
    test_mock_instance_method()
    test_regular_methods_still_work()
    test_mock_signature_checking()
    test_other_mock_types()
    print("All comprehensive tests passed!")

